GOAL: Fix an injected bug in /luxon/src/zones/fixedOffsetZone.js so that these two hidden tests pass:
  - `FixedOffsetZone is invalid when constructed with a non-numeric offset`
  - `A DateTime in an invalid FixedOffsetZone is itself invalid`

Current content of the file (read it yourself to confirm) is:

```js
import { formatOffset, signedOffset } from "../impl/util.js";
import Zone from "../zone.js";

let singleton = null;

export default class FixedOffsetZone extends Zone {
  static get utcInstance() {
    if (singleton === null) {
      singleton = new FixedOffsetZone(0);
    }
    return singleton;
  }

  static instance(offset) {
    return offset === 0 ? FixedOffsetZone.utcInstance : new FixedOffsetZone(offset);
  }

  static parseSpecifier(s) {
    if (s) {
      const r = s.match(/^utc(?:([+-]\d{1,2})(?::(\d{2}))?)?$/i);
      if (r) {
        return new FixedOffsetZone(signedOffset(r[1], r[2]));
      }
    }
    return null;
  }

  constructor(offset) {
    super();
    this.fixed = offset;
  }

  get type() { return "fixed"; }
  get name() { return this.fixed === 0 ? "UTC" : `UTC${formatOffset(this.fixed, "narrow")}`; }
  offsetName() { return this.name; }
  formatOffset(ts, format) { return formatOffset(this.fixed, format); }
  get universal() { return true; }
  offset() { return this.fixed; }
  equals(otherZone) { return otherZone.type === "fixed" && otherZone.fixed === this.fixed; }
  get isValid() { return true; }   // <-- suspicious: always true
}
```

So a `FixedOffsetZone` built from a non-numeric offset (e.g. `FixedOffsetZone.instance("blorp")` or `new FixedOffsetZone("blorp")`) currently claims to be valid, and a DateTime placed in such a zone is considered valid too. The expected behaviour is that such a zone is invalid, and a DateTime in it is invalid (`DateTime.local().setZone(zone).isValid === false` — note `DateTime#setZone` already returns `DateTime.invalid(unsupportedZone(zone))` when `!zone.isValid`, so making the zone report invalid should be enough).

